"""Build the static help, finder and reference pages from the evidence inventory."""
from pathlib import Path
import json,html,re
D=Path('dist');origin='https://rinksideclock.com';esc=lambda x:html.escape(str(x),quote=True)
coverage=json.loads((D/'coverage.json').read_text());rows=coverage['controllers']
nav='<a href="start-here.html">Start here</a><a href="controllers.html">Find your controller</a><a href="manuals.html">Manuals</a>'
footer='<footer class="resource-footer"><span>RINKSIDE CLOCK · INDEPENDENT HOCKEY TIMEKEEPER PRACTICE</span><nav aria-label="Help and information"><a href="start-here.html">Start here</a><a href="about.html">About</a><a href="faq.html">FAQ</a><a href="contact.html">Contact</a><a href="privacy.html">Privacy</a><a href="coverage.html">Coverage & limits</a></nav></footer>'
def page(slug,title,description,body,script=''):
 full=title+' | Rinkside Clock';url=origin+'/'+slug+'.html';image=origin+'/assets/rinkside-clock-social-v1.png'
 head=f'<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(full)}</title><meta name="description" content="{esc(description)}"><link rel="canonical" href="{url}"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="controllers.css"><link rel="stylesheet" href="experience.css"><link rel="stylesheet" href="resources.css">'
 for key,value in {'type':'website','site_name':'Rinkside Clock','title':full,'description':description,'url':url,'image':image,'image:secure_url':image,'image:type':'image/png','image:width':'1200','image:height':'600','image:alt':'Rinkside Clock. Practice before puck drop. Free hockey timekeeper simulators.'}.items():head+=f'<meta property="og:{key}" content="{esc(value)}">'
 for key,value in {'card':'summary_large_image','title':full,'description':description,'image':image,'image:alt':'Rinkside Clock. Practice before puck drop.'}.items():head+=f'<meta name="twitter:{key}" content="{esc(value)}">'
 (D/(slug+'.html')).write_text('<!doctype html><html lang="en"><head>'+head+'</head><body class="resource-page"><header><a class="brand" href="./">◷ <b>Rinkside Clock</b></a><nav class="site-nav" aria-label="Main navigation">'+nav+'</nav></header><main>'+body+footer+'</main>'+script+'</body></html>')
def hero(kicker,title,text):return f'<div class="resource-hero"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p>{text}</p></div>'
def section(title,body,id=''):return f'<section class="help-section"'+(f' id="{id}"' if id else '')+f'><h2>{title}</h2>{body}</section>'
rule='https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Officiating/Downloads/2026-28-hc-rulebook-e.pdf'
guide=hero('YOUR FIRST SHIFT','A calmer first game.','Start with the job. Then learn the buttons. A practical introduction for hockey clock volunteers.')
guide+='<nav class="guide-toc" aria-label="Guide contents"><a href="#before">Before the game</a><a href="#during">During play</a><a href="#penalties">Penalties</a><a href="#timing">Period lengths</a><a href="#first-shift">First-shift checklist</a></nav>'
guide+=section('Before you touch the clock.','<ol><li><b>Confirm the game format.</b> Ask for the period and warm-up lengths, stop-time or running-time rules, timeout entitlement, overtime format and the rink curfew.</li><li><b>Meet the other officials.</b> Agree who operates the clock, records goals and penalties, manages the doors and communicates with the referee.</li><li><b>Identify the installed controller.</b> Read its model label and compare the hockey insert. A scoreboard brand alone does not identify its controller.</li><li><b>Check the setup with arena staff.</b> Confirm the connection, home/visitor assignment, time display and horn. Never reset an active rink controller to practise.</li></ol><a class="resource-button" href="controllers.html">Find my controller →</a>','before')
guide+=section('Watch the play, especially at a faceoff.','<p>In stop-time hockey, start the clock when the puck is legally dropped. Stop it at the whistle. Keep your hand ready and your attention on the official, rather than anticipating the drop or watching the display.</p><p>Record a goal only after the referee awards it. Note the clock reading and confirm the team, scorer and assists with the scorekeeper. For a penalty, confirm the team, jersey, duration and any special treatment before entering it.</p><p>If you start or stop late, stop making further changes and tell the referee at the next safe opportunity. The referee decides disputed time; use the controller’s correction procedure to enter the instructed value.</p>','during')
guide+=section('Penalty basics.','<p>These are introductory descriptions of Hockey Canada rules. Your competition may use specific adaptations; ask the referee how a penalty should be displayed and when a player may return.</p><div class="help-table-wrap"><table class="help-table"><thead><tr><th>Penalty</th><th>What the timekeeper needs to know</th></tr></thead><tbody><tr><th>Minor / bench minor</th><td>Normally two minutes of playing time. A qualifying opposing goal can end the eligible minor on the shorthanded team. Confirm which penalty ends; do not erase every penalty when a goal is scored.</td></tr><tr><th>Double minor</th><td>Two consecutive minor penalties, not a single major. Treat the segments separately when applying a goal-related release.</td></tr><tr><th>Major</th><td>Five minutes. A goal does not end it. Hockey Canada also assesses a game misconduct; the officials identify the substitute serving the time.</td></tr><tr><th>Coincidental</th><td>Equal-duration penalties assessed to opposite teams at the same stoppage. The referee applies the cancellation rules and identifies any remaining time penalty. Do not assume both should appear as manpower penalties on the board. Junior/Senior variations can differ.</td></tr><tr><th>Misconduct</th><td>Ten minutes of playing time for the player; by itself it does not make the team shorthanded. Return is at the first stoppage after expiry. Track it as instructed, separately from a manpower penalty.</td></tr><tr><th>Queued / delayed start</th><td>A third time penalty may wait while two run. The serving order matters. A delayed penalty signalled during play is a different situation; wait for the official’s assessment before entering it.</td></tr></tbody></table></div><p>Never use the end of a visible timer alone to decide a player’s release in a complex penalty situation. Coordinate with the penalty timekeeper and referee.</p><p class="source-note">References: <a href="'+rule+'#page=49">Hockey Canada 2026–2028, rules 4.2–4.7</a> and <a href="'+rule+'#page=77">off-ice officials, rules 5.5–5.7</a>. Reviewed 25 October 2026.</p>','penalties')
guide+=section('There is no single minor-hockey period length.','<p>Do not assume that the simulator’s 15-minute default is your league’s format. Confirm all three period lengths, whether the clock stops at every whistle, and whether a mercy rule changes the timing. Running time, curfews, warm-ups, shift horns and timeouts are separate instructions.</p><form class="shift-plan" id="shift-plan"><h3>Make a first-shift note</h3><p>This stays on this page. Print it or write it down.</p><div class="form-grid"><label>League / division<input name="division" maxlength="80" placeholder="e.g. U13 local league"></label><label>Period lengths<input name="periods" maxlength="80" placeholder="Confirm with your league"></label><label>Timing format<select name="timing"><option>Confirm before the game</option><option>Stop time</option><option>Running time</option><option>Mixed / local rule</option></select></label><label>Warm-up, timeout & curfew<input name="notes" maxlength="160" placeholder="Ask the referee / league contact"></label></div><button type="button" id="print-plan">Print guide & notes</button></form>','timing')
guide+=section('Your first-shift checklist.','<div class="shift-checklist">'+''.join('<label><input type="checkbox"> '+t+'</label>' for t in ['I know the controller model and have practised setting time.','The period lengths, timing format, warm-up and curfew are confirmed.','I can start, stop, correct the time, enter a goal and enter / clear a penalty.','I know who will confirm penalty details and player releases.','The home and visitor teams and starting period are correct.','I know how to reach arena staff if the equipment fails.'])+'</div><p>After the game, confirm the final score and follow the league’s game-sheet and equipment handover procedure.</p><div class="help-actions"><a class="resource-button" href="controllers.html">Choose a simulator →</a><a href="faq.html">Read common questions</a></div>','first-shift')
page('start-here','Hockey timekeeping: start here','Learn first-shift hockey timekeeping basics, penalties, period timing and an equipment checklist before practising your rink controller.',guide,'<script src="resources.js"></script>')
about=hero('ABOUT','Practice before puck drop.','Rinkside Clock is a free, independent place to learn hockey scoreboard controls before your shift at the rink.')
about+=section('Built around the equipment you actually use.','<p>The simulators recreate documented hockey workflows and recognizable controller layouts. Guided lessons explain a sequence, Test yourself gives an outcome to achieve, and free practice lets you explore.</p><p>The project is maintained by <a href="https://github.com/davejcameron">David Cameron</a>. Source code, corrections and change history are public on <a href="https://github.com/davejcameron/rink-timekeeper">GitHub</a>.</p>')
about+=section('What “coverage” means here.','<p>Twelve playable training profiles are supported by manuals, local guides and reference images. They are fixed training configurations, not complete hardware or firmware emulators. A manufacturer manual, a photographed hockey insert and a Canadian arena report establish different facts; we label them separately.</p><p>The directory is not a census of Canadian rinks. Evidence is strongest in Ontario, British Columbia and Alberta. Regional reports and unresolved models are tracked on the <a href="coverage.html">coverage page</a>.</p><p>Rinkside Clock is not affiliated with the equipment manufacturers or a governing hockey organization. Simulator progress is practice feedback, not officiating certification.</p>')
about+=section('Help improve the next shift.','<p>Found a different insert, missing controller or incorrect sequence? Please include the model label, hockey overlay, manual link and arena name in a <a href="contact.html">controller report</a>. We verify evidence before treating a profile as a match.</p>')
page('about','About Rinkside Clock','Learn how Rinkside Clock builds independent hockey timekeeper simulators and verifies controller sources.',about)
faqs=[('Which simulator should I choose?','Read the label on your console and compare its hockey insert with the reference images. Use the <a href="controllers.html">arena and panel finder</a>. A matching brand or a code such as 871 alone does not identify every chassis.'),('How long are the periods?','Your league or tournament sets the format. Confirm period lengths, stop time versus running time, warm-up, timeouts and curfew before the game. The 15-minute practice default is not a rules recommendation.'),('Should a goal clear a penalty automatically?','No simulator clears one solely because a score changed. An eligible minor may terminate when the opposing team scores while it is shorthanded. Majors and coincidental penalties require different handling. Confirm the release with the official; see <a href="start-here.html#penalties">penalty basics</a>.'),('Why are some buttons disabled?','These are training profiles. Hardware configuration menus, other sports, auxiliary equipment and some hockey functions remain outside specific profiles. Each simulator shows its unsupported control count and links to its limits. A disabled control is not a statement that the real device lacks it.'),('Why does the horn make no sound?','Tap Sound on and interact with the page to unlock browser audio. Check device volume, silent mode and browser sound permission. A visual horn response can still appear when sound is muted.'),('What is the difference between tutorials and Test yourself?','Tutorials show the button sequence. Test rounds use shuffled scenarios with variable clock targets, scores and player numbers. Revealing the solution or restarting marks the task assisted; skips appear in the review.'),('Can I connect this to the scoreboard at my rink?','No. These pages practise locally in the browser. They do not transmit commands to rink equipment.'),('Where are the manuals?','The <a href="manuals.html">manuals index</a> separates manufacturer manuals, association-hosted copies and local quick guides. Manuals for researched but unplayable controllers are included too.'),('Is my arena listed with its current equipment?','Arena reports show their source date and match confidence. Equipment and inserts can change. Always check the installed model; a regional brand report is not an exact controller match.'),('Does every controller have a remote?','No. Seven profiles have playable documented accessories. Others have unverified compatibility or optional equipment outside the current training configuration. Do not substitute a handset from another family.'),('Do you save my scores or test results?','Practice and test results live in the current page session and reset on reload. The site does not require an account. See <a href="privacy.html">Privacy</a> for hosting and external-link details.'),('How do I report a missing model or a problem?','Use the <a href="contact.html">report composer</a> to prepare a GitHub issue. Include a reproducible sequence, the model and a public manual or source. Reports are public once you submit them on GitHub.')]
faq=hero('FAQ','A few things before your shift.','Answers about the simulator, your controller and the job at the clock.')+''.join('<details class="help-faq"><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in faqs)
page('faq','Hockey timekeeper simulator FAQ','Answers about hockey clock operation, penalty releases, audio, test mode, controller coverage and manuals.',faq)
privacy=hero('PRIVACY','Practice stays on your device.','Last updated 25 October 2026.')
privacy+=section('Simulator data.','<p>The application does not require an account and does not send game scores, penalty entries, tutorial completion or test results to an application database. Those values are held in the current page’s memory and reset when you reload or close it. First-shift notes and report drafts are also kept in the page until you navigate away.</p><p>The application code does not add advertising pixels, behavioural analytics or application cookies. Controller reference images used in the library are served with the site. Optional external reference images and manuals may contact the third-party host when opened or loaded.</p>')
privacy+=section('Hosting and security services.','<p>This static site is hosted using OpenAI Sites and delivered through Cloudflare. Those providers receive normal web requests, which can include IP address, browser information, requested URL and timing. The delivery layer may set security or bot-management cookies. Their processing and retention are governed by their own policies; we do not claim that visiting this site produces no server logs.</p><p><a href="https://openai.com/policies/privacy-policy/">OpenAI privacy policy</a> · <a href="https://www.cloudflare.com/privacypolicy/">Cloudflare privacy policy</a></p>')
privacy+=section('GitHub reports and external links.','<p>The Contact page builds a report draft in your browser. Nothing is submitted by that form. Choosing “Review on GitHub” puts the draft in a GitHub issue URL so you can edit and submit it there; GitHub receives that URL and its contents. A submitted issue is public. Do not include player details, passwords, private contact information or photos of children.</p><p>External manuals and organization links have their own privacy policies. To request a correction or discuss this page, use <a href="contact.html">Contact</a>. For removal of information posted in a GitHub issue, contact the repository maintainer through that issue or GitHub support.</p>')
page('privacy','Privacy','How Rinkside Clock handles browser-local practice, hosting requests and public GitHub reports.',privacy)
contact=hero('CONTACT & CORRECTIONS','Help make the next shift easier.','Report a bug, suggest a controller or correct an arena record. We use public GitHub issues.')
contact+='<section class="help-section"><h2>Prepare your report.</h2><p>No GitHub account is needed to draft the report here. You will need one to submit it on GitHub. Nothing is sent automatically.</p><form id="report-form"><div class="form-grid"><label>Report type<select name="type"><option>Bug report</option><option>Missing controller</option><option>Arena / source correction</option><option>General question</option></select></label><label>Controller / model<input name="model" maxlength="100" placeholder="Model label or simulator name"></label><label>Arena, city & province / territory<input name="arena" maxlength="150" placeholder="Optional; include the rink number"></label><label>Public source or manual URL<input name="source" type="url" maxlength="1000" placeholder="https://…"></label></div><label>What should we know?<textarea name="details" required minlength="10" maxlength="5000" rows="6" placeholder="For a bug: steps, expected result, actual result, device/browser. For a controller: label, hockey insert and a public manual."></textarea></label><p class="source-note">Submitted issues are public. Leave out personal information and photos of players.</p><button class="resource-button" type="submit">Prepare report</button><div id="report-preview" hidden><h3>Your draft</h3><pre id="report-body"></pre><a class="resource-button" id="report-github" target="_blank" rel="noreferrer">Review on GitHub ↗</a><button type="button" id="copy-report">Copy report</button><p id="report-status" role="status"></p></div></form></section><p><a href="https://github.com/davejcameron/rink-timekeeper/issues">Browse existing issues</a> · <a href="https://github.com/davejcameron/rink-timekeeper">View source code</a></p>'
page('contact','Contact & report a controller','Prepare a public GitHub issue for a bug, missing controller, arena update or timekeeping simulator question.',contact,'<script src="resources.js"></script>')
finder=hero('CONTROLLER FINDER','Find the panel in front of you.','Start with an arena report, a recognizable feature, or the model label. Always compare the installed hockey insert before practising.')
finder+='<div class="finder-tabs" role="group" aria-label="Choose a way to find your controller"><button data-finder="arena" aria-pressed="true">By arena</button><button data-finder="visual" aria-pressed="false">By appearance</button><button data-finder="model" aria-pressed="false">By model</button></div><section class="help-section" id="finder-arena"><h2>Look up a documented arena.</h2><p>These are sourced reports, not a live equipment inventory. Each match shows its age and confidence.</p><div class="form-grid"><label>Arena or city<input type="search" id="arena-search" placeholder="e.g. Panorama, Cambridge, Ottawa"></label><label>Province / territory<select id="arena-region"><option value="">All provinces & territories</option></select></label></div><p id="arena-count" role="status"></p><div id="arena-results" class="arena-results"></div><p>No match? <button class="text-button" data-finder="visual">Identify by appearance</button> or <a href="contact.html">report your arena</a>.</p></section><section class="help-section" id="finder-visual" hidden><h2>What does your panel look like?</h2><p>Choose a distinctive feature, then compare the photos. This is a guided visual comparison, not automatic image recognition.</p><div id="visual-choices" class="visual-choices"></div><p id="visual-status" role="status"></p><div id="visual-results" class="controller-library"></div></section><section class="help-section" id="finder-model" hidden><h2>Read the model label.</h2><label>Brand, model or key legend<input type="search" id="model-search" placeholder="e.g. ISC9000, K2-28, PR04200"></label><p id="model-count" role="status"></p><div id="model-results" class="controller-library"></div></section>'
page('controllers','Find your hockey score clock controller','Identify your rink controller through sourced arena reports, a visual panel-matching flow or model search.',finder,'<script src="catalog.js"></script><script src="finder.js"></script>')
# A standalone, static index remains useful without JavaScript.
manuals=hero('MANUALS & QUICK GUIDES','The right instructions. One place.','Manufacturer manuals, association-hosted copies and local rink guides, with their provenance kept visible.')
manuals+='<label class="manual-search">Filter by brand, model or document type<input id="manual-search" type="search" placeholder="e.g. OES, manufacturer manual, Rotomatic"></label><p id="manual-count" role="status"></p><div id="manual-list">'
for c in rows:
 name=c['name'];kind='Manufacturer manual';host='Manufacturer website'
 if 'Rotomatic' in name or 'Sportstimer' in name:kind='Local rink operating guide';host='Cambridge Roadrunners · 2016';
 elif 'VisionTime' in name:kind='Manufacturer-authored manual';host='Greater Victoria Minor Ball Hockey mirror'
 elif 'HDD 2000' in name:kind='Manufacturer-authored manual';host='ERRA association mirror'
 elif 'Scoretec' in name:kind='Manufacturer-authored manual';host='Hockey Calgary mirror'
 elif 'Eversan' in name:kind='Manufacturer product specification';host='Specification sheet · operating manual not located'
 elif 'Other leads:' in name:kind='Community research lead';host='Unverified lead · not a manufacturer manual'
 elif 'ISC9000' in name:kind='Manufacturer-authored manual';host='Burlington Ringette mirror · J12 v1.3'
 elif 'ISC85X' in name:kind='Local hockey operating guide';host='NMHOP association mirror'
 elif '871' in name:host='ERRA association mirror'
 elif 'MPC-4' in name:host='Hockey Calgary mirror'
 elif not c['url'] and not c['source'].lower().endswith('.pdf'):kind='Reference / support library';host='Exact operating manual may still be missing'
 elif not c['url']:host='Manufacturer source · no simulator yet'
 manuals+=f'<article class="manual-card" data-search="{esc((name+kind+host).lower())}"><div><span class="doc-type">{esc(kind)}</span><h2>{esc(name)}</h2><p>{esc(host)}</p></div><div class="manual-links"><a href="{esc(c["source"])}" target="_blank" rel="noreferrer">Open document / source ↗</a>'+(f'<a href="{esc(c["url"])}">Open simulator →</a>' if c['url'] else '<span>Research reference · not playable</span>')+f'</div><p class="manual-limit">{esc(c["limits"])}</p></article>'
manuals+='</div><p>Files remain on the linked host. A manufacturer-authored manual hosted by an association is a mirror, not a manufacturer-hosted download. Rotomatic currently has a local guide, not a located manufacturer manual.</p>'
page('manuals','Hockey score clock manuals & controller guides','Find operating manuals and local guides for Daktronics, Hamilton, OES, Nevco, Fair-Play, Scoretec, Harris Time and Rotomatic.',manuals,'<script src="resources.js"></script>')
print('Built seven reference and finder pages')
